<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nucleus | Borrower Application</title>
<link rel="preconnect" href="https://fonts.bunny.net"><link href="https://fonts.bunny.net/css?family=dm-sans:400,500,600,700&display=swap" rel="stylesheet">
<style>
:root{--navy:#071b61;--blue:#0876f9;--cyan:#00a7ff;--line:#cce2f8;--muted:#56709a;--pale:#edf7ff;--green:#16c986}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#f9fdff,#e5f5ff);color:var(--navy);font-family:'DM Sans',Arial,sans-serif}.shell{max-width:1320px;margin:auto;padding:20px 24px 34px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.brand{display:flex;gap:10px;align-items:center;font-weight:700;font-size:25px;letter-spacing:-1px}.brand small{display:block;font-size:8px;font-weight:500;letter-spacing:0;margin-top:-3px}.orb{width:38px;height:38px;border:5px solid #057eff;border-radius:50%;box-shadow:inset 0 0 0 3px #b9edff,0 0 0 2px #0a3994;position:relative;flex:none}.orb:after{content:'';position:absolute;width:11px;height:11px;border-radius:50%;background:#062d90;right:-5px;top:8px;box-shadow:-15px 13px 0 #00abff}.top-title{text-align:center}.top-title h1{margin:0;font-size:24px;letter-spacing:-.8px}.top-title p{margin:3px 0 0;font-size:13px;color:#153b8e}.tag{font-size:10px;font-weight:700;letter-spacing:4px;color:#0756d7;white-space:nowrap}.app{min-height:690px;display:grid;grid-template-columns:245px 1fr;overflow:hidden;border:1px solid #bddbf7;border-radius:12px;background:#fff;box-shadow:0 14px 42px #2065b022}aside{padding:26px 18px;border-right:1px solid #d9eafb;background:linear-gradient(#fbfeff,#eef8ff)}.aside-brand{display:flex;align-items:center;gap:7px;font-weight:700;font-size:18px;margin-bottom:28px}.aside-brand .orb{transform:scale(.55);margin:-8px}.steps{display:grid;gap:9px}.step{display:flex;gap:11px;align-items:center;padding:10px 9px;border-radius:7px;color:#43628d;font-size:12px;font-weight:500;cursor:pointer}.step.active{background:linear-gradient(90deg,#dff0ff,#edf8ff);color:#0064eb;font-weight:700}.step.done{color:#174c91}.num{width:20px;height:20px;display:grid;place-items:center;border:1.5px solid #8bb3e6;border-radius:50%;font-size:10px;flex:none}.active .num{background:var(--blue);border-color:var(--blue);color:white}.done .num{background:var(--green);border-color:var(--green);color:white}.chev{margin-left:auto;font-size:17px;color:var(--blue)}main{display:flex;flex-direction:column;padding:30px 36px 24px;min-width:0}.head{display:flex;justify-content:space-between;align-items:flex-start;gap:15px}.head h2{margin:0 0 4px;font-size:25px;letter-spacing:-.8px}.head p{margin:0;color:var(--muted);font-size:13px}.save{padding:8px 13px;border:1px solid #bbdafa;border-radius:7px;background:#f6fbff;color:#0756c8;font-size:11px;font-weight:700}.content{width:100%;max-width:760px;margin:30px auto 0}.form{display:grid;grid-template-columns:1fr 1fr;gap:16px}.field{display:grid;gap:6px;font-size:11px;font-weight:600;color:#405b8a}.full{grid-column:1/-1}.field input,.field select{height:40px;width:100%;border:1px solid #c9ddf5;border-radius:6px;padding:0 12px;background:#fcfeff;color:#15346d;font-size:13px;outline:0}.field input:focus,.field select:focus{border-color:var(--blue);box-shadow:0 0 0 3px #e5f2ff}.toggle-row{display:flex;align-items:center;gap:13px;margin-bottom:18px;padding-bottom:18px;border-bottom:1px solid #e2eefb;font-size:13px;font-weight:700}.toggle{width:34px;height:19px;border-radius:20px;background:var(--blue);position:relative}.toggle:after{content:'';width:15px;height:15px;position:absolute;right:2px;top:2px;border-radius:50%;background:#fff}.help{display:block;margin-top:2px;color:#58719b;font-size:11px;font-weight:400}.check{margin-top:18px;padding:14px;border:1px solid #c8e2fb;border-radius:7px;background:#eaf5ff;color:#264e85;font-size:12px}.check input{accent-color:var(--blue);margin-right:7px}.actions{display:flex;justify-content:space-between;align-items:center;margin-top:auto;padding-top:34px}.back{border:0;background:none;color:#075fce;font-size:13px;font-weight:600}.next{padding:13px 32px;border:0;border-radius:7px;color:white;background:linear-gradient(100deg,#006df5,#00a4ff);box-shadow:0 8px 16px #b8ddff;font-size:13px;font-weight:700;cursor:pointer}.tabs{display:flex;overflow:hidden;margin-bottom:18px;border-radius:7px;background:#e8f4ff}.tabs button{flex:1;padding:10px;border:0;background:transparent;color:#31588d;font-size:12px;font-weight:700}.tabs .on{border-radius:6px;background:linear-gradient(90deg,#0678f9,#0496ff);color:#fff}.list{display:grid;gap:9px}.row{display:grid;grid-template-columns:35px 1fr auto auto;align-items:center;gap:10px;padding:10px;border:1px solid #d5e8fa;border-radius:7px}.icon{width:27px;height:27px;display:grid;place-items:center;border-radius:6px;background:#e3f3ff;color:#0675f5;font-weight:700}.row b{font-size:13px}.row small{display:block;margin-top:2px;color:#6680a8;font-size:10px}.amount{font-weight:700;font-size:13px}.link{color:#0875ed;font-size:11px;font-weight:700}.total{display:flex;justify-content:space-between;margin-top:16px;padding:13px;border:1px solid #cfe6fa;border-radius:7px;background:#edf7ff;font-size:14px;font-weight:700}.upload{margin-top:18px;padding:30px;border:1.5px dashed #8fc5fc;border-radius:8px;background:#f8fcff;text-align:center;color:#2870c7;font-size:13px}.upload strong{display:block;margin-bottom:6px;font-size:15px}.review{overflow:hidden;border:1px solid #cfe1f5;border-radius:8px}.review h3{margin:0;padding:13px 16px;background:#f8fcff;font-size:15px}.review div{display:flex;justify-content:space-between;padding:9px 16px;border-top:1px solid #e1edf8;font-size:12px}.review span:last-child{font-weight:700}.success{display:flex;align-items:center;gap:10px;margin:18px 0;padding:14px;border:1px solid #b8efd6;border-radius:8px;background:#edfff7;color:#08734a;font-size:13px}.success i{width:23px;height:23px;display:grid;place-items:center;border-radius:50%;background:var(--green);color:#fff;font-style:normal;font-weight:700}.progress{display:flex;align-items:center;margin:26px 16px 0}.progress span{height:2px;flex:1;background:#b9d7f6}.progress i{width:13px;height:13px;border:2px solid #87b5e9;border-radius:50%;background:#fff}.progress i.done{border-color:var(--green);background:var(--green)}.progress i.current{border-color:var(--blue);background:var(--blue)}
@media(max-width:800px){.shell{padding:14px}.tag{display:none}.top-title{text-align:right}.top-title h1{font-size:17px}.top-title p{display:none}.app{grid-template-columns:1fr;min-height:0}aside{padding:12px;border-right:0;border-bottom:1px solid #d9eafb;overflow-x:auto}.aside-brand{display:none}.steps{display:flex;width:max-content}.step{padding:7px 8px}.step span:not(.num):not(.chev),.chev{display:none}main{min-height:620px;padding:25px 18px}.content{margin-top:24px}.head h2{font-size:22px}.form{grid-template-columns:1fr}.full{grid-column:auto}.row{grid-template-columns:30px 1fr auto}.row .link{display:none}}
</style></head><body><div class="shell">
<header class="top"><div class="brand"><span class="orb"></span><span>Nucleus<small>Lending Made Smarter.™</small></span></div><div class="top-title"><h1>Borrower Application (POS)</h1><p>A simple, secure, and guided experience from start to finish.</p></div><div class="tag">REAL PEOPLE. BRIGHTER POSSIBILITIES.™</div></header>
<section class="app"><aside><div class="aside-brand"><span class="orb"></span>Nucleus</div><nav class="steps" id="steps"></nav></aside><main><div class="head"><div><h2 id="title"></h2><p id="subtitle"></p></div><button class="save">Save &amp; Exit</button></div><div class="content" id="content"></div><div class="actions"><button class="back" id="back">←&nbsp; Back</button><button class="next" id="next">Continue&nbsp; →</button></div></main></section><div class="progress" id="progress"></div>
</div><script>
const labels=['Personal Info','Co-Borrower','Property & Loan','Employment','Income','Assets','Liabilities','Real Estate Owned','Declarations','Documents','Review & Submit'];
const form=a=>'<div class="form">'+a+'</div>',field=(l,v,full='')=>'<label class="field '+full+'">'+l+'<input value="'+v+'"></label>',select=(l,v)=>'<label class="field">'+l+'<select><option>'+v+'</option></select></label>';
const pages=[
['Personal Information','Tell us a bit about yourself.',form(field('First Name','John')+field('Last Name','Doe')+field('Date of Birth','04/15/1990')+field('Social Security Number','•••-••-6789')+select('Marital Status','Married')+select('Citizenship Status','U.S. Citizen')+field('Phone Number','(555) 123-4567')+field('Email Address','john.doe@example.com')+field('Current Address','1234 Maple Dr, Austin, TX 78701','full')+select('How long have you lived here?','3 - 5 years')+select('Housing Status','Own'))],
['Co-Borrower Information','Add a co-borrower to your application.','<div class="toggle-row"><span class="toggle"></span><span>Add a co-borrower<small class="help">A co-borrower can help you qualify and may provide additional income.</small></span></div>'+form(field('First Name','Sarah')+field('Last Name','Smith')+field('Date of Birth','06/22/1992')+field('Social Security Number','•••-••-4321')+select('Relationship to You','Spouse')+field('Email Address','sarah.smith@example.com')+field('Phone Number','(555) 987-6543'))+'<div class="check"><input type="checkbox" checked>Use the same address as primary borrower<span class="help" style="margin-left:23px">1234 Maple Dr, Austin, TX 78701</span></div>'],
['Property & Loan','Tell us about the home and financing you need.',form(field('Property Address','1234 Maple Dr, Austin, TX 78701','full')+select('Property Type','Single Family Home')+select('Occupancy','Primary Residence')+field('Purchase Price','$450,000')+field('Down Payment','$90,000 (20%)')+field('Requested Loan Amount','$360,000')+select('Loan Purpose','Purchase'))],
['Employment & Income','Tell us about your employment and income.','<div class="tabs"><button class="on">Primary Employment</button><button>Additional Income</button></div>'+form(field('Employer Name','Tech Solutions Inc.')+select('Employment Type','W-2 Employee')+field('Job Title','Senior Software Engineer')+field('Start Date','03/2020')+field('Monthly Gross Income','$12,500')+select('Income Frequency','Monthly'))+'<div class="check"><input type="checkbox" checked>I am currently employed here</div>'],
['Assets & Liabilities','Tell us about your financial assets and liabilities.','<div class="tabs"><button class="on">Assets</button><button>Liabilities</button></div><div class="list">'+[['▣','Chase Checking','Checking •••• 4587','$25,000'],['◆','Chase Savings','Savings •••• 2291','$75,000'],['◈','Fidelity Investments','Investment •••• 7742','$120,000']].map(x=>'<div class="row"><span class="icon">'+x[0]+'</span><span><b>'+x[1]+'</b><small>'+x[2]+'</small></span><span class="amount">'+x[3]+'</span><span class="link">Edit</span></div>').join('')+'</div><div class="total"><span>Total Assets</span><span>$220,000</span></div><div class="check"><b>Need help?</b><span class="help">You can add additional accounts later or provide documentation during the document upload step.</span></div>'],
['Upload Documents','Upload the required documents to support your application.','<div class="tabs"><button class="on">Required Documents (5)</button><button>Additional Documents</button></div><div class="list">'+[['Government ID','Driver’s license, passport, or state ID'],['Proof of Income','Last 30 days of pay stubs'],['Bank Statements','Last 2 months'],['W-2 Forms','Last 2 years'],['Asset Statements','Investment, retirement, etc.']].map((x,i)=>'<div class="row"><span class="icon">▤</span><span><b>'+x[0]+'</b><small>'+x[1]+'</small></span><span class="link">'+(i===1?'✓ Uploaded':'Upload ›')+'</span></div>').join('')+'</div><div class="upload"><strong>☁ Drag &amp; drop files here or click to upload</strong><small>PDF, DOC, DOCX, JPG, PNG (Max 10MB each)</small></div>'],
['Review & Submit','Review your information before submitting.','<div class="review"><h3>Application Summary</h3>'+[['Property Type','Single Family (Purchase)'],['Purchase Price','$450,000'],['Down Payment','$90,000 (20%)'],['Loan Amount','$360,000'],['Primary Borrower','John Doe'],['Co-Borrower','Sarah Smith'],['Total Monthly Income','$18,750'],['Total Assets','$220,000']].map(x=>'<div><span>'+x[0]+'</span><span>'+x[1]+'</span></div>').join('')+'</div><div class="success"><i>✓</i><span>I certify that the information provided is true and complete to the best of my knowledge.</span></div>']
];let current=0,steps=document.querySelector('#steps'),content=document.querySelector('#content'),next=document.querySelector('#next'),back=document.querySelector('#back');
function render(){let p=pages[current];document.querySelector('#title').textContent=p[0];document.querySelector('#subtitle').textContent=p[1];content.innerHTML=p[2];steps.innerHTML=labels.map((x,i)=>'<div class="step '+(i===current?'active':i<current?'done':'')+'" data-i="'+i+'"><span class="num">'+(i<current?'✓':i+1)+'</span><span>'+x+'</span><span class="chev">›</span></div>').join('');document.querySelectorAll('.step').forEach(e=>e.onclick=()=>{current=+e.dataset.i;render()});back.style.visibility=current?'visible':'hidden';next.innerHTML=current===pages.length-1?'Submit Application&nbsp; →':'Continue&nbsp; →';document.querySelector('#progress').innerHTML=labels.map((_,i)=>'<i class="'+(i<current?'done':i===current?'current':'')+'"></i>'+(i<10?'<span></span>':'')).join('')}
next.onclick=()=>{if(current<pages.length-1){current++;render()}else{content.innerHTML='<div class="success"><i>✓</i><span>Your application has been submitted successfully. We will be in touch shortly.</span></div>';next.style.display='none'}};back.onclick=()=>{if(current){current--;render()}};render();
</script></body></html>
